//! apt.dat — X-Plane airport data.
//!
//! Measured from shipped content (`Custom Scenery/KSEA Demo Area/Earth nav data/apt.dat`
//! sha `8bd4153e…`, v1050; `Custom Scenery/Global Airports/Earth nav data/apt.dat` with
//! 3 455 airports; older packs at v1000/850/715):
//!
//! ```text
//! I or A                             <- line-ending marker; both occur in shipped packs
//! 1050 Generated by WorldEditor      <- "<version> <generator>"
//! 1    433 1 0 KSEA Seattle Tacoma Intl   <- airport: seq, helicopter?, ?, name…
//! 1302 icao_code KSEA               <- airport metadata, one tag per record
//! 100 46.02 2 1 … 16L … 34R …        <- runway, 26 whitespace-separated fields
//! 110 1 0.00 0.0000 Road 0          <- polygon/path group
//! 111  47.46492315 -122.30935191    <-   its line records
//! 112  …                            <-   … and width records
//! ```
//!
//! **These files carry no indentation.** Every record starts at column 0, so the hierarchy
//! is implied purely by adjacency: a `111` belongs to the `110` immediately before it, a
//! `101` to the `100` before it. Grouping here is therefore driven by record type, and any
//! record whose parent is absent is reported rather than silently attached.
//!
//! Field *semantics* are only claimed where a value is self-evidently identifiable (a
//! runway designator, a lat/lon pair that matches the airport's recorded datum). Other
//! fields stay positional; see `tests/golden/aptdat/ksea_summary.txt`.

use std::collections::BTreeMap;

use anyhow::{bail, Context, Result};

/// One apt.dat record: its numeric type plus its whitespace-separated fields.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Record {
    /// The leading integer that names the record type.
    pub kind: u32,
    /// Field 0 is the type token itself, matching the file.
    pub fields: Vec<String>,
    /// The line exactly as written.
    pub raw: String,
}

impl Record {
    pub fn field(&self, i: usize) -> Option<&str> {
        self.fields.get(i).map(|s| s.as_str())
    }

    pub fn f64(&self, i: usize) -> Option<f64> {
        self.field(i)?.trim().parse::<f64>().ok()
    }
}

/// A runway (`100`) and the records attached to it.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Runway {
    pub record: Record,
    /// `101` runway-extension records that follow it.
    pub children: Vec<Record>,
}

impl Runway {
    /// Positions and designators are assigned by field index; the mapping was verified
    /// against KSEA's recorded datum, not taken from a spec.
    pub fn end1_name(&self) -> Option<&str> {
        self.record.field(8)
    }
    pub fn end1_lat(&self) -> Option<f64> {
        self.record.f64(9)
    }
    pub fn end1_lon(&self) -> Option<f64> {
        self.record.f64(10)
    }
    pub fn end2_name(&self) -> Option<&str> {
        self.record.field(17)
    }
    pub fn end2_lat(&self) -> Option<f64> {
        self.record.f64(18)
    }
    pub fn end2_lon(&self) -> Option<f64> {
        self.record.f64(19)
    }

    /// Both designators, e.g. `"16L/34R"`.
    pub fn identity(&self) -> String {
        match (self.end1_name(), self.end2_name()) {
            (Some(a), Some(b)) => format!("{a}/{b}"),
            (Some(a), None) => a.to_string(),
            _ => String::new(),
        }
    }
}

/// A group that owns `111`/`112`/`113` line records.
///
/// The opener set is measured, not assumed. Across the seven shipped apt.dat files
/// (3 558 000 line records) the immediately preceding group opener is always one of:
/// `110` (taxiway/polygon), `120` (airport object), `130` (airport boundary) or `114`.
/// Treating only `110` as an opener orphans 367 records in `Global Airports/apt.dat` alone.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct LineGroup {
    pub opener: Record,
    /// `111` lines, `112` widths and `113` beziers, in file order.
    pub lines: Vec<Record>,
}

/// Record types that own following `111`/`112`/`113` records, measured from shipped data.
pub const LINE_GROUP_OPENERS: [u32; 4] = [110, 114, 120, 130];

/// Record types that continue the runway they follow *contiguously*. Measured: of 784 `101`
/// records only 70 directly follow a `100`; the rest follow `16`, `1302` or `17`, so `101`
/// is attached to a runway only when it is contiguous with one.
pub const RUNWAY_CONTINUATIONS: [u32; 1] = [101];

/// One airport: the `1` header and everything up to the next `1`.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Airport {
    pub header: Record,
    /// Every record in file order, header excluded.
    pub records: Vec<Record>,
    pub runways: Vec<Runway>,
    pub line_groups: Vec<LineGroup>,
}

impl Airport {
    /// `1 <seq> <helicopter> <…> <name>` — the name is the remainder of the line.
    pub fn name(&self) -> &str {
        let f = &self.header.fields;
        if f.len() > 4 {
            self.header
                .raw
                .splitn(f.len(), ' ')
                .last()
                .unwrap_or("")
                .trim()
        } else {
            ""
        }
    }

    pub fn seq(&self) -> Option<u32> {
        self.header.field(1)?.trim().parse::<u32>().ok()
    }

    /// `1302 <tag> <value>` pairs, in file order.
    pub fn metadata(&self) -> Vec<(String, String)> {
        let mut out = Vec::new();
        for r in self.records.iter().filter(|r| r.kind == 1302) {
            let tag = r.field(1).unwrap_or("").to_string();
            let value = r.fields.get(2..).map(|v| v.join(" ")).unwrap_or_default();
            out.push((tag, value));
        }
        out
    }

    pub fn metadata_value(&self, tag: &str) -> Option<String> {
        self.metadata()
            .into_iter()
            .find(|(t, _)| t == tag)
            .map(|(_, v)| v)
    }

    /// ICAO identifier when the airport publishes one.
    pub fn icao(&self) -> Option<String> {
        self.metadata_value("icao_code")
    }

    /// Freestanding airport objects (`120`). These also open line groups, which is why they
    /// appear in [`Airport::line_groups`] as well.
    pub fn objects(&self) -> Vec<&Record> {
        self.records.iter().filter(|r| r.kind == 120).collect()
    }
}

/// A parsed apt.dat file.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct AptDat {
    pub line_ending_marker: String,
    pub version: u32,
    /// The remainder of line 2, e.g. `Generated by WorldEditor`.
    pub generator: String,
    /// Records before the first `1`, if the file has any.
    pub preamble: Vec<Record>,
    pub airports: Vec<Airport>,
    /// Lines that carried no numeric record type (blank or non-conforming).
    pub skipped_lines: Vec<(usize, String)>,
}

impl AptDat {
    pub fn load(path: impl AsRef<std::path::Path>) -> Result<AptDat> {
        let path = path.as_ref();
        let text = crate::read_text_lossy(path)
            .with_context(|| format!("reading apt.dat {}", path.display()))?;
        AptDat::parse(&text).with_context(|| format!("parsing apt.dat {}", path.display()))
    }

    pub fn parse(text: &str) -> Result<AptDat> {
        let mut lines = text.lines();
        // Measured across the seven shipped apt.dat files: the marker is 'I' in three
        // (KSEA, KLAL, KOSH) and 'A' in four (Global Airports, default apt dat, LOWI, Mars),
        // so both are accepted. Line 2 is "<version> <generator>", where the generator text
        // can be a whole GPL notice (Mars nav data, v715).
        let marker = lines.next().unwrap_or("").trim_end().to_string();
        if !matches!(marker.as_str(), "I" | "M" | "A") {
            bail!("line 1: expected apt.dat marker 'I', 'M' or 'A', got {marker:?}");
        }
        let second = lines.next().unwrap_or("").trim_end().to_string();
        let mut it = second.splitn(2, ' ');
        let (Some(ver_raw), generator) = (it.next(), it.next().unwrap_or("")) else {
            bail!("line 2: expected \"<version> <generator>\", got {second:?}");
        };
        let version = ver_raw
            .parse::<u32>()
            .with_context(|| format!("line 2: bad apt.dat version {ver_raw:?}"))?;

        let mut preamble: Vec<Record> = Vec::new();
        let mut airports: Vec<Airport> = Vec::new();
        let mut skipped: Vec<(usize, String)> = Vec::new();
        let mut prev_kind: Option<u32> = None;

        for (n, raw) in lines.enumerate() {
            let line_no = n + 3; // 1-based, after the two header lines
            let line = raw.trim_end();
            if line.trim().is_empty() {
                continue;
            }
            let fields: Vec<String> = line.split_whitespace().map(|s| s.to_string()).collect();
            let kind = fields[0].parse::<u32>().with_context(|| {
                format!(
                    "line {line_no}: expected a numeric record type, got {:?}",
                    fields[0]
                )
            })?;
            let record = Record {
                kind,
                fields,
                raw: line.to_string(),
            };

            if kind == 1 {
                airports.push(Airport {
                    header: record,
                    records: Vec::new(),
                    runways: Vec::new(),
                    line_groups: Vec::new(),
                });
                continue;
            }

            let Some(airport) = airports.last_mut() else {
                preamble.push(record);
                continue;
            };

            // Adjacency rules, because these files have no indentation to express nesting.
            // `prev_kind` is the record type immediately before this one, which is what the
            // measured parent table is keyed on.
            if (111..=113).contains(&kind) {
                match airport.line_groups.last_mut() {
                    Some(g) => g.lines.push(record.clone()),
                    None => skipped.push((line_no, format!("orphan record {line}"))),
                }
            } else if RUNWAY_CONTINUATIONS.contains(&kind) && prev_kind == Some(100) {
                match airport.runways.last_mut() {
                    Some(r) => r.children.push(record.clone()),
                    None => skipped.push((line_no, format!("orphan record {line}"))),
                }
            }

            if kind == 100 {
                airport.runways.push(Runway {
                    record: record.clone(),
                    children: Vec::new(),
                });
            } else if LINE_GROUP_OPENERS.contains(&kind) {
                airport.line_groups.push(LineGroup {
                    opener: record.clone(),
                    lines: Vec::new(),
                });
            }
            airport.records.push(record);
            prev_kind = Some(kind);
        }

        Ok(AptDat {
            line_ending_marker: marker,
            version,
            generator: generator.to_string(),
            preamble,
            airports,
            skipped_lines: skipped,
        })
    }

    /// Every record in the file, airports included, in file order.
    pub fn all_records(&self) -> Vec<&Record> {
        let mut out: Vec<&Record> = self.preamble.iter().collect();
        for a in &self.airports {
            out.push(&a.header);
            out.extend(a.records.iter());
        }
        out
    }

    /// Record type → count, over the whole file.
    pub fn record_counts(&self) -> BTreeMap<u32, usize> {
        let mut m: BTreeMap<u32, usize> = BTreeMap::new();
        for r in self.all_records() {
            *m.entry(r.kind).or_default() += 1;
        }
        m
    }

    pub fn airport_count(&self) -> usize {
        self.airports.len()
    }

    /// Find an airport by ICAO identifier.
    pub fn find_icao(&self, icao: &str) -> Option<&Airport> {
        self.airports
            .iter()
            .find(|a| a.icao().as_deref() == Some(icao))
    }
}
